const rows = new Map();
let counter = 0;
function issue(userId) {
  for (const [token, row] of rows) if (row.userId === userId) rows.delete(token);
  const token = `t${++counter}`;
  rows.set(token, { userId, expiresAt: 100 });
  return token;
}
function redeem(token, now) {
  const row = rows.get(token);
  if (!row) return null;
  rows.delete(token);
  return row.expiresAt > now ? row.userId : null;
}

const a = issue("u-ada");
const b = issue("u-ada");
console.log(redeem(a, 10), redeem(b, 10), redeem(b, 10));
const c = issue("u-ada");
console.log(redeem(c, 150), redeem(c, 50));

