const key = crypto.getRandomValues(new Uint8Array(32));
const hmacKey = await crypto.subtle.importKey("raw", key, { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
const toHex = (buf) => Array.from(new Uint8Array(buf), (b) => b.toString(16).padStart(2, "0")).join("");
const mac = async (text) => toHex(await crypto.subtle.sign("HMAC", hmacKey, new TextEncoder().encode(text)));

async function sign(data, exp) {
  const payload = btoa(JSON.stringify({ data, exp }));
  return `${payload}.${await mac(payload)}`;
}

async function verify(value, now) {
  const [payload, signature] = value.split(".");
  if (signature !== (await mac(payload))) return "bad signature";
  const { data, exp } = JSON.parse(atob(payload));
  if (exp <= now) return "expired";
  return data;
}

const value = await sign({ attachment: 7 }, 1000);
console.log(await verify(value, 500));
console.log(await verify(value, 1000));
console.log(await verify(btoa(JSON.stringify({ data: { attachment: 8 }, exp: 1000 })) + "." + value.split(".")[1], 500));

