function loadKey(base64) {
  if (!base64) throw new Error("encryption key is not set");
  const bytes = Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));
  if (bytes.length !== 32) throw new Error(`encryption key must be 32 bytes, got ${bytes.length}`);
  return bytes;
}

const good = btoa(String.fromCharCode(...crypto.getRandomValues(new Uint8Array(32))));
for (const value of [good, "c2hvcnQ=", undefined]) {
  try {
    console.log("loaded", loadKey(value).length, "bytes");
  } catch (error) {
    console.log(error.message);
  }
}

